if (product !== 'sos') throw new Error('unsupported_product');
if (resource !== 'eop') throw new Error('unsupported_resource');
const planId = text(fields.plan_id);
if (!/^[A-Za-z0-9_@.:+-]{1,256}$/.test(planId)) throw new Error('record_id_invalid');
const approvalId = text(fields.approval_id);
if (approvalId && !/^[A-Za-z0-9_@.:+-]{1,256}$/.test(approvalId)) throw new Error('approval_id_invalid');
